81	
82	// WithSessionMetadataOnly reads session metadata without transcript or prompts.
83	func WithSessionMetadataOnly() ReadOption {
84		return func(opts *readOptions) {
85			opts.mode = sessionReadMetadataOnly
86		}
87	}
88	
89	// WithSessionMetadataAndPrompts reads metadata and prompts without transcript.
90	func WithSessionMetadataAndPrompts() ReadOption {
