162	// SessionReader reads committed session documents.
163	type SessionReader interface {
164		ReadSession(ctx context.Context, ref SessionRef, opts ...ReadOption) (*SessionContent, error)
165	}
166	
167	// SessionWriter writes and backfills committed session documents.
168	type SessionWriter interface {
169		WriteSession(ctx context.Context, ref SessionRef, session Session) error
170		UpdateSession(ctx context.Context, ref SessionRef, opts ...WriteOption) error
171	}
